      if (u && (u.input_tokens != null || u.cache_read_input_tokens != null)) {
        const used =
          (u.input_tokens || 0) +
          (u.cache_read_input_tokens || 0) +
          (u.cache_creation_input_tokens || 0);
        return { pct: Math.min(100, Math.round((used / limit) * 100)), tokens: used };
      }
    }
  } catch (_) { /* ignore */ }
  return null;
}

// ── MCP status from local config ────────────────────────────────
// Native stdin carries no MCP state, so we report how many MCP servers are
// configured (project .mcp.json + user ~/.claude.json). Best-effort count.
function mcpStatus() {
  let count = 0;
  const tryFile = (p, pick) => {
    try {
      if (!fs.existsSync(p)) return;
      const j = JSON.parse(fs.readFileSync(p, 'utf8'));
      const servers = pick(j);
      if (servers) count += Object.keys(servers).length;
    } catch (_) { /* ignore */ }
  };
  tryFile(path.join(process.cwd(), '.mcp.json'), (j) => j.mcpServers);
  tryFile(path.join(os.homedir(), '.claude.json'), (j) => j.mcpServers);
  return count;
}

// ── formatting ──────────────────────────────────────────────────
function fmtDuration(ms) {
  if (!ms || ms < 0) return null;
  const s = Math.floor(ms / 1000);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  if (h) return `${h}h${String(m).padStart(2, '0')}m`;
  if (m) return `${m}m${String(sec).padStart(2, '0')}s`;
  return `${sec}s`;
}

function ctxColor(pct) {
  if (pct >= 85) return red;
  if (pct >= 60) return yellow;
  return green;
}

// ── main ────────────────────────────────────────────────────────
function main() {
  const data = readStdin();
  const parts = [];

  // model
  const model =
    (data.model && (data.model.display_name || data.model.id)) || 'claude';
  parts.push(cyan(model));

  // ctx%
  const ctx = contextPct(data);
  if (ctx) parts.push(ctxColor(ctx.pct)(`${ctx.pct}% ctx`));

  // elapsed
  const dur = fmtDuration(data.cost && data.cost.total_duration_ms);
  if (dur) parts.push(dim(dur));

  // mcp
  const mcp = mcpStatus();
  parts.push(dim(`mcp ${mcp}`));

  // cost
  const hideCost = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_HIDE_COST || '');
  if (!hideCost && data.cost && typeof data.cost.total_cost_usd === 'number') {
    const sym = process.env.LUNA_SL_COST_SYMBOL ?? '$';
    parts.push(green(`${sym}${data.cost.total_cost_usd.toFixed(2)}`));
  }

  process.stdout.write(parts.join(sep));
}

main();

